ee:message.ee:set-payload:
%dw 2.0
output application/json

// Guardamos el status en una variable local para que sea más fácil de leer
var statusCode = vars.vRespuesta.status
var responseBody = vars.vRespuesta.payload
var customerData = responseBody.GetPartnerViewResponse.GetPartnerViewResult.Customer
var individualRole = customerData.IndividualRole
---
{
  "code": statusCode as String,

  // Validación del mensaje
  "message": if (statusCode == 200) "Subscriber retrieved successfully" 
             else "Not Subscriber retrieved",

  // Validación de la data: si es 200 mapea, si no, devuelve objeto vacío o null
  "data": if (statusCode == 200) {
    "id": customerData.ID,
    "serviceSpecification": {
      "name": "OTT"
    },
    "state": {
      "id": customerData.status.id,
      "name": customerData.status.name
    },
    "customer": [
      {
        "id": customerData.ID,
        "name": individualRole.NameUsing.IndividualNames.formattedName,
        "givenNames": individualRole.NameUsing.IndividualNames.givenNames,
        "familyNames": individualRole.NameUsing.IndividualNames.familyNames,
        "middleNames": individualRole.NameUsing.IndividualNames.middleNames default "",
        "aristocraticTitle": individualRole.NameUsing.IndividualNames.aristocraticTitle,
        "aliveDuring": {
          "startDateTime": individualRole.aliveDuring.startDateTime
        },
        "identifiedBy": individualRole.IdentifiedBy.IndividualIdentifications map (item) -> {
          "scan": item.scan,
          "cardNr": item.cardNr
        },
        "contactMedium": customerData.ContactableVia.ContactMedium map (item) -> {
          "eMailAddress": item.eMailAddress,
          "addressId": item.AddressId,
          "eMailProtocol": item.eMailProtocol
        },
        "address": customerData.AddressList.UrbanPropertyAddress map (item) -> {
          "addressCode": item.addressCode default "",
          "city": item.city,
          "streetNrFirst": item.streetNrFirst,
          "locality": item.locality,
          "streetName": item.streetName,
          "postCode": item.postCode
        }
      }
    ],
    "serviceCharacteristic": [
      {
        "name": "customerInquiryList",
        "value": responseBody.GetPartnerViewResponse.GetPartnerViewResult.CustomerInquiryList.CustomerInquiry filter ($ != "") map (item) -> {
            "description": item.description,
            "id": item.id
        }
      },
      {
        "name": "customerProductList",
        "value": responseBody.GetPartnerViewResponse.GetPartnerViewResult.CustomerProductList.Product filter ($ != "") map (item) -> {
            "productStatus": {
                "name": item.statusName,
                "id": item.statusId
            },
            "productCategory": {
                "description": item.description,
                "id": item.categoryId
            }
        }
      }
    ]
  } else {} // Aquí devuelve un objeto vacío si no es 200
}
